package com.stayease.model;

import java.time.LocalDate;

/** The data needed to insert a booking (id and createdAt are generated by the database). */
public record NewBooking(
    String bookingRef,
    String guestName,
    String email,
    String mobile,
    int roomId,
    LocalDate checkIn,
    LocalDate checkOut,
    int guests,
    int nights,
    int totalPrice,
    String status) {}
